def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    class Point:
        def __init__(self, **kwargs):
            for key, value in kwargs.items():
                setattr(self, key, value)

        def __repr__(self):
            return f"{self.__class__.__name__}({', '.join(f'{k}={v}' for k, v in self.__dict__.items())})"

    for field, (type_, default) in fields.items():
        setattr(Point, field, property(lambda self, field=field: getattr(self, field), lambda self, value, field=field: setattr(self, field, value), doc=f"{field} ({type_}): {default}"))

    for srid, wkt in srid_map.items():
        Point.srid_to_wkt[srid] = wkt

    Point.srid_to_wkt = {}

    return Point

