    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def wraps(fn):
        @wraps(fn)
        def newfunc(*args, **kwargs):
            k = key(*args, **kwargs)
            try:
                with (lock[k] if lock else nullcontext()):
                    res = cache[k]
            except KeyError:
