def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """

    fromquence = False

    if seq.is_type('FillRequest'):
        fromquence = True
    elif seq.is_type('Sequence'):
        if any(e.type == 'FillRequest' for e in iterchildren(seq)):
            fromquence = True

    # Check that it's not a Source sequence
    if seq.is_type('Sequence') and any(e.type == 'Source' for e in iterchildren(seq)):
        fromquence = False

    return fromquence

