def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.left or coord > self.right:
        return

    bin_index = int((coord - self.left) / self.binsize)
    if bin_index >= 0 and bin_index < len(self.hist):
        self.hist[bin_index] += weight

