def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    output = "\t" * indent + self.__class__.__name__ + ":\n"
    output += "\t" * (indent + 1) + "content:\n"
    output += "\t" * (indent + 2) + str(self.content) + "\n"
    if self.attributes:
        output += "\t" * (indent + 1) + "attributes:\n"
        for key, value in self.attributes.items():
            output += "\t" * (indent + 2) + str(key) + " = " + str(value) + "\n"
    if self.children:
        output += "\t" * (indent + 1) + "children:\n"
        for.child in self.children:
            output += "\t" * (indent + 2) + child.pretty(indent + 2, debug) + "\n"
    if debug:
        output += "\t" * (indent + 1) + "id: " + str(self.id) + "\n"
        output += "\t" * (indent + 1) + "doc: " + str(self.doc) + "\n"
    return output

