def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if isinstance(arg, tuple):
            if len(arg) == 2 and arg[0] and arg[0] == arg[1]:
                result.append(arg[0])
            else:
                result.append(arg)
        else:
            result.append(arg)
    return result

