def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).
    """
    import subprocess

    if not isinstance(commands, list):
        commands = [commands]

    for command in commands:
        if verbose:
            print(f"Running command: {command} with args: {args}")

        process = subprocess.Popen([command] + args, cwd=cwd, env=env, stderr=subprocess.STDOUT if hide_stderr else None)
        output, _ = process.communicate()
        returncode = process.returncode

        if verbose:
            print(f"Command output: {output.decode('utf-8')}")

        if returncode != 0:
            raise subprocess.CalledProcessError(returncode, command, output.decode('utf-8'))

