def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re

    def replace_tags(match):
        tag = match.group(2)
        if replacer:
            return replacer(tag)
        return tag

    tag_set = set()
    pattern = re.compile(r'(```[^\n]*\n[^\n]*\n```|<[^>]*>|{[^}]*}|[^\s\W]+)')
    result = []
    current_code_block = False

    for match in pattern.finditer(text):
        if match.group(1).startswith('```'):
            current_code_block = not current_code_block
        elif not current_code_block and match.group(2):
            tag_set.add(match.group(2))
            if replacer:
                result.append(replace_tags(match))
            else:
                result.append(match.group(0))
        else:
            result.append(match.group(0))

    return tag_set, ''.join(result)

