def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """

    optspec = []

    if command_name:
        pass

    for c in self.commands:
        if c.optgroup and c.name == command_name:
            command = c
            break
    else:  # this else corresponds to the for loop
        raise OptionNameError("Unknown command " + command_name)

    if argument_name in command.arguments:
        arg = command.arguments[argument_name]
        optspec = []

        if arg.output:
            optspec.append('O')

        if arg.value_required:
            optspec.append('1')

        if arg.required:
            optspec.append('!')

    elif 'all' in command.arguments:
        for arg in command.arguments.values():
            optspec.extend(get_option_spec(self, arg.name))
    elif 'optional' in command.arguments:
        pass
    else:
        raise OptionNameError("Unknown argument " + argument_name)

    if command.optspec:
        if command.optspec == '-':
            optspec.append('O')

    if not optspec:
        optspec.append('+')

    return optspec

